-- Insert Lessons
INSERT INTO public.lessons (id, module_id, title, order_index, type, content, xp_reward, duration_minutes, is_published)
VALUES ('a0000000-0000-0000-0000-000000000001'::uuid, 'a0000000-0000-0000-0000-000000000011'::uuid, 'Introduction to Graphic Design & Visual Literacy', 1, 'video', '{"video_url": "https://www.youtube.com/embed/sTi5SNgxE3U", "notes": "## What is Graphic Design?\n\nGraphic design is the art of planning and projecting ideas with visual content.\n\n### The Double Diamond Framework\n1. **Discover** - Research and understand the problem\n2. **Define** - Synthesize and define the challenge\n3. **Develop** - Generate and test solutions\n4. **Deliver** - Finalize and launch\n\n### AI + Design\nThis course takes an AI-First approach.", "resources": [{"title": "What is Graphic Design? (AIGA)", "url": "https://www.aiga.org/resources/what-is-graphic-design", "type": "article"}, {"title": "The Double Diamond (Design Council)", "url": "https://www.designcouncil.org.uk/our-resources/the-double-diamond/", "type": "article"}]}'::jsonb, 100, 180, true);
INSERT INTO public.lessons (id, module_id, title, order_index, type, content, xp_reward, duration_minutes, is_published)
VALUES ('a0000000-0000-0000-0000-000000000002'::uuid, 'a0000000-0000-0000-0000-000000000011'::uuid, 'Elements of Design', 2, 'interactive', '{"text_content": "## Elements of Design\n\nThe seven elements: Line, Shape, Color, Value, Texture, Space, Form.\n\n**Line** defines boundaries and guides the eye.\n**Shape** can be geometric or organic.\n**Value** creates depth and contrast.\n**Texture** adds richness.\n**Space** includes positive and negative.\n**Form** is 3D quality.", "brief": "### Figma Exercise\n\nCreate a composition using all seven elements. Use the Elements Starter File.", "resources": [{"title": "Figma Basics Playlist", "url": "https://www.youtube.com/playlist?list=PLXDU_eVOJTx7QIDShq4KyE4LhWjxJ4M4n", "type": "video"}, {"title": "Elements of Design Guide", "url": "https://www.canva.com/learn/design-elements/", "type": "article"}]}'::jsonb, 100, 180, true);
INSERT INTO public.lessons (id, module_id, title, order_index, type, content, xp_reward, duration_minutes, is_published)
VALUES ('a0000000-0000-0000-0000-000000000003'::uuid, 'a0000000-0000-0000-0000-000000000011'::uuid, 'Principles of Design', 3, 'interactive', '{"text_content": "## Principles of Design\n\n**Balance** - symmetrical or asymmetrical visual weight.\n**Contrast** - light/dark, large/small differences.\n**Emphasis** - the focal point.\n**Movement** - the path the eye follows.\n**Pattern** - repetition for consistency.\n**Rhythm** - repeating elements with variation.\n**Unity** - all parts working together.", "brief": "### Moodboard Exercise\n\nCreate a moodboard demonstrating each principle with real-world examples.", "resources": [{"title": "Principles of Design - Full Course (Envato Tuts+)", "url": "https://www.youtube.com/watch?v=9EPTM91TBDU", "type": "video"}, {"title": "Design Principles Guide", "url": "https://www.interaction-design.org/literature/topics/design-principles", "type": "article"}]}'::jsonb, 100, 180, true);
INSERT INTO public.lessons (id, module_id, title, order_index, type, content, xp_reward, duration_minutes, is_published)
VALUES ('a0000000-0000-0000-0000-000000000004'::uuid, 'a0000000-0000-0000-0000-000000000011'::uuid, 'Practice + Support Day', 4, 'interactive', '{"text_content": "## Studio Practice Session\n\n### Peer Critique Guidelines\n- Be specific about what works and why\n- Be constructive - suggest alternatives\n- Be respectful - critique the work, not the person\n\nToday: review Days 1-3, apply feedback, experiment.", "brief": "Revise your moodboard based on peer feedback. Improve at least two areas.", "resources": [{"title": "How to Give Design Feedback (NNGroup)", "url": "https://www.nngroup.com/articles/design-critiques/", "type": "article"}]}'::jsonb, 50, 180, true);
INSERT INTO public.lessons (id, module_id, title, order_index, type, content, xp_reward, duration_minutes, is_published)
VALUES ('a0000000-0000-0000-0000-000000000005'::uuid, 'a0000000-0000-0000-0000-000000000011'::uuid, 'Weekly Studio Challenge', 5, 'project', '{"brief": "## Week 1 Challenge: Social Media Post\n\nCreate a social media post (Instagram 1080x1080 or LinkedIn 1200x627) for a fictional brand.\n\nMust apply at least 3 elements and 2 principles of design.\nInclude a clear focal point and visual hierarchy.\nExport as PNG with a brief write-up.", "notes": "Be prepared for a 3-minute presentation.", "resources": [{"title": "Social Media Image Sizes", "url": "https://buffer.com/library/social-media-image-sizes/", "type": "article"}, {"title": "Beginning Graphic Design (GCFLearnFree)", "url": "https://www.youtube.com/watch?v=srbrw4HRo6o", "type": "video"}]}'::jsonb, 150, 180, true);
INSERT INTO public.lessons (id, module_id, title, order_index, type, content, xp_reward, duration_minutes, is_published)
VALUES ('a0000000-0000-0000-0000-000000000006'::uuid, 'a0000000-0000-0000-0000-000000000012'::uuid, 'Color Theory Fundamentals', 6, 'video', '{"video_url": "https://www.youtube.com/embed/_2LLXnUdUIc", "notes": "## Color Theory\n\n**Color Wheel**: Primary (RYB) -> Secondary (orange, green, purple) -> Tertiary.\n\n**Harmony**: Complementary (opposite), Analogous (adjacent), Triadic (even), Monochromatic (one hue).\n\n**Psychology**: Blue=trust, Red=urgency, Green=growth, Yellow=optimism.\n\n**Accessibility**: WCAG AA contrast (4.5:1).", "resources": [{"title": "Adobe Color", "url": "https://color.adobe.com", "type": "tool"}, {"title": "Coolors", "url": "https://coolors.co", "type": "tool"}, {"title": "WCAG Contrast Checker", "url": "https://webaim.org/resources/contrastchecker/", "type": "tool"}]}'::jsonb, 100, 180, true);
INSERT INTO public.lessons (id, module_id, title, order_index, type, content, xp_reward, duration_minutes, is_published)
VALUES ('a0000000-0000-0000-0000-000000000007'::uuid, 'a0000000-0000-0000-0000-000000000012'::uuid, 'Typography Basics', 7, 'video', '{"video_url": "https://www.youtube.com/embed/sByzHoiYFX0", "notes": "## Typography Basics\n\n**Type Classifications**: Serif (formal), Sans-serif (modern), Script (decorative), Display (headlines).\n\n**Pairing Tips**: Use contrasting styles. Limit to 2-3 typefaces. Use hierarchy through size and weight.", "resources": [{"title": "Google Fonts", "url": "https://fonts.google.com", "type": "tool"}, {"title": "Font Knowledge", "url": "https://fonts.google.com/knowledge", "type": "article"}]}'::jsonb, 100, 180, true);
INSERT INTO public.lessons (id, module_id, title, order_index, type, content, xp_reward, duration_minutes, is_published)
VALUES ('a0000000-0000-0000-0000-000000000008'::uuid, 'a0000000-0000-0000-0000-000000000012'::uuid, 'Layout & Composition (Grids and White Space)', 8, 'interactive', '{"text_content": "## Grid Systems\n\n**Manuscript** - single column (books)\n**Column** - multiple columns (magazines, web)\n**Modular** - columns + rows (dashboards)\n**Hierarchical** - flexible, content-driven\n\n**White Space** improves readability by 20%, creates hierarchy, feels premium.\n\n**Figma Auto Layout** uses padding and spacing for responsive components.", "brief": "Apply a grid system to your Week 1 social post. Then create a version with intentional white space. Compare.", "resources": [{"title": "Grid Systems Guide", "url": "https://www.interaction-design.org/literature/topics/grid-systems", "type": "article"}, {"title": "Figma Auto Layout", "url": "https://help.figma.com/hc/en-us/articles/360040451374-Add-auto-layout-to-a-frame", "type": "docs"}]}'::jsonb, 100, 180, true);
INSERT INTO public.lessons (id, module_id, title, order_index, type, content, xp_reward, duration_minutes, is_published)
VALUES ('a0000000-0000-0000-0000-000000000009'::uuid, 'a0000000-0000-0000-0000-000000000012'::uuid, 'Typography + Color Studio', 9, 'interactive', '{"text_content": "## Studio Session: Color + Type\n\nEnsure readability with high contrast text. Use color to establish hierarchy. Test designs in grayscale first, then add color.", "brief": "Create a typographic poster for a design conference. Include: event name, date, location, tagline. Use a 3-5 color palette, 2 typefaces, and a grid.", "resources": [{"title": "Type Connection", "url": "https://typeconnection.net", "type": "tool"}]}'::jsonb, 50, 180, true);
INSERT INTO public.lessons (id, module_id, title, order_index, type, content, xp_reward, duration_minutes, is_published)
VALUES ('a0000000-0000-0000-0000-000000000010'::uuid, 'a0000000-0000-0000-0000-000000000012'::uuid, 'Weekly Studio Challenge', 10, 'project', '{"brief": "## Week 2 Challenge: Typographic Poster\n\nCreate a 24x36in portrait poster demonstrating:\n- A deliberate color harmony\n- At least 2 paired typefaces\n- A clear grid system\n- Intentional white space\n\nExport as PDF + PNG.", "notes": "Poster can be for any fictional event, brand, or cause.", "resources": [{"title": "Super Practical Guide to Color Theory (DesignerUp)", "url": "https://www.youtube.com/watch?v=GyVMoejbGFg", "type": "video"}, {"title": "Poster Design Inspiration", "url": "https://dribbble.com/search/poster", "type": "article"}]}'::jsonb, 150, 180, true);
INSERT INTO public.lessons (id, module_id, title, order_index, type, content, xp_reward, duration_minutes, is_published)
VALUES ('a0000000-0000-0000-0000-000000000011'::uuid, 'a0000000-0000-0000-0000-000000000013'::uuid, 'Branding Fundamentals', 11, 'video', '{"video_url": "https://www.youtube.com/embed/pR7tMnKghDs", "notes": "## Branding Fundamentals\n\n**Brand Identity** = how the brand wants to be perceived.\n**Brand Image** = how it is actually perceived.\n\n**Strategy**: Mission, Vision, Values, Target Audience, Brand Personality.\n\n**Competitive Analysis**: Research 3 competitors - strengths, weaknesses, opportunities.", "resources": [{"title": "Brand Strategy Guide", "url": "https://www.interaction-design.org/literature/topics/branding", "type": "article"}]}'::jsonb, 100, 180, true);
INSERT INTO public.lessons (id, module_id, title, order_index, type, content, xp_reward, duration_minutes, is_published)
VALUES ('a0000000-0000-0000-0000-000000000012'::uuid, 'a0000000-0000-0000-0000-000000000013'::uuid, 'Logo Design Basics', 12, 'interactive', '{"text_content": "## Logo Types\n\n**Wordmark** - stylized text (Google, Coca-Cola)\n**Lettermark** - initials (IBM, HBO)\n**Pictorial mark** - icon (Apple, Twitter)\n**Abstract mark** - symbol (Nike, Adidas)\n**Combination mark** - icon + text (Mastercard)\n**Emblem** - icon inside text (Starbucks)\n\nStart with 50+ thumbnail sketches on paper. Narrow to 3, digitize in Figma.", "brief": "Sketch 20 logo concepts. Narrow to 3 strongest and digitize in Figma. Present with justification.", "resources": [{"title": "How to Design a Logo - Full Course (DesignCourse)", "url": "https://www.youtube.com/watch?v=UyoXKGQrmtY", "type": "video"}, {"title": "Logo Design Process", "url": "https://www.logodesignlove.com/logo-design-process", "type": "article"}]}'::jsonb, 100, 180, true);
INSERT INTO public.lessons (id, module_id, title, order_index, type, content, xp_reward, duration_minutes, is_published)
VALUES ('a0000000-0000-0000-0000-000000000013'::uuid, 'a0000000-0000-0000-0000-000000000013'::uuid, 'Branding Studio Day', 13, 'interactive', '{"text_content": "## Brand Application Studio\n\nApply your logo to: business card, social media, website header, product mockup.\n\n### Peer Review\n1. Does it communicate brand personality?\n2. Is it scalable (16px to 1000px)?\n3. Does it work in black and white?\n4. Is it distinctive and memorable?", "brief": "Create brand mockups for at least 3 touchpoints. Share with a partner for peer review.", "resources": [{"title": "Designing a Brand from Scratch (Duda Creative)", "url": "https://www.youtube.com/watch?v=AP7eD1K2UpI", "type": "video"}]}'::jsonb, 50, 180, true);
INSERT INTO public.lessons (id, module_id, title, order_index, type, content, xp_reward, duration_minutes, is_published)
VALUES ('a0000000-0000-0000-0000-000000000014'::uuid, 'a0000000-0000-0000-0000-000000000013'::uuid, 'Weekly Studio Challenge', 14, 'project', '{"brief": "## Week 3 Challenge: Brand Pitch\n\nCreate a brand identity pitch deck including:\n1. Brand Strategy (mission, vision, values, audience)\n2. Logo (primary + variations)\n3. Color Palette with hex values\n4. Typography (headline + body)\n5. Brand Applications (3+ mockups)\n6. Usage Guidelines\n\nPresent as a 5-minute pitch.", "notes": "Tell a story - who the brand is and why the identity brings it to life.", "resources": [{"title": "Brand Identity Design Process (Anik Jain)", "url": "https://www.youtube.com/watch?v=4uWtmSzCcpY", "type": "video"}, {"title": "Brand Guidelines Examples", "url": "https://www.canva.com/learn/brand-guidelines/", "type": "article"}]}'::jsonb, 150, 180, true);
INSERT INTO public.lessons (id, module_id, title, order_index, type, content, xp_reward, duration_minutes, is_published)
VALUES ('a0000000-0000-0000-0000-000000000015'::uuid, 'a0000000-0000-0000-0000-000000000013'::uuid, 'Print Design Principles', 15, 'video', '{"video_url": "https://www.youtube.com/embed/WvY4OMJVE9M", "notes": "## Print Design Principles\n\n**CMYK** for print vs **RGB** for screens.\n**300 DPI** minimum resolution.\n**Bleed**: 0.125in on all sides.\n**Safe zone**: 0.125in from trim.\n\nExport as PDF/X-4 with embedded fonts and crop marks.", "resources": [{"title": "Print-Ready File Checklist", "url": "https://www.printivity.com/print-ready-file-checklist/", "type": "article"}, {"title": "How to Create Effective Print Design (tonybydesign)", "url": "https://www.youtube.com/watch?v=WvY4OMJVE9M", "type": "video"}]}'::jsonb, 100, 180, true);
INSERT INTO public.lessons (id, module_id, title, order_index, type, content, xp_reward, duration_minutes, is_published)
VALUES ('a0000000-0000-0000-0000-000000000016'::uuid, 'a0000000-0000-0000-0000-000000000014'::uuid, 'Business Card Design', 16, 'project', '{"brief": "## Business Card Design\n\nDesign a 3.5x2in business card representing your brand.\n\n**Specs**: 0.125in bleed, 300 DPI, CMYK, front + back.\n\n**Required**: Logo, Name, Title, Contact info, Social handles, Brand accent color.\n\nExport as print-ready PDF with crop marks.", "notes": "Export as print-ready PDF with crop marks and bleed.", "resources": [{"title": "Business Card Templates", "url": "https://www.canva.com/business-cards/templates/", "type": "tool"}, {"title": "Print-Ready Files Guide", "url": "https://www.printful.com/blog/print-ready-files", "type": "article"}]}'::jsonb, 150, 180, true);
INSERT INTO public.lessons (id, module_id, title, order_index, type, content, xp_reward, duration_minutes, is_published)
VALUES ('a0000000-0000-0000-0000-000000000017'::uuid, 'a0000000-0000-0000-0000-000000000014'::uuid, 'Print Studio Day', 17, 'interactive', '{"text_content": "## Print File Audit\n\n### Checklist\n- [ ] Correct document size\n- [ ] 0.125in bleed all sides\n- [ ] Content within safe zone\n- [ ] 300 DPI resolution\n- [ ] CMYK color mode\n- [ ] Fonts embedded or outlined\n- [ ] PDF/X-4 export\n- [ ] Crop marks\n\nAudit your file, review a partner''s, fix issues.", "brief": "Finalize business card files based on audit feedback. Submit print-ready PDF.", "resources": []}'::jsonb, 50, 180, true);
INSERT INTO public.lessons (id, module_id, title, order_index, type, content, xp_reward, duration_minutes, is_published)
VALUES ('a0000000-0000-0000-0000-000000000018'::uuid, 'a0000000-0000-0000-0000-000000000014'::uuid, 'Month-End Studio Challenge', 18, 'project', '{"brief": "## Month 1 Portfolio Presentation\n\nGallery walk format. Include:\n1. Elements & Principles moodboard (Week 1)\n2. Social media post (Week 1 Challenge)\n3. Typographic poster (Week 2 Challenge)\n4. Brand identity pitch deck (Week 3 Challenge)\n5. Business card (Week 4)\n\n5 min per student. Show process. Explain 2 key decisions.", "notes": "Cumulative assessment for Graphic Design Foundations.", "resources": []}'::jsonb, 200, 180, true);
